1	// Resolves @portside/dispatch/* to src/* (the path alias in jsconfig.json). Node does not read jsconfig.json;
2	// the suite preloads this hook through tools/testing/setup.mjs.
3	import { existsSync } from "node:fs";
4	import { dirname, join } from "node:path";
5	import { fileURLToPath, pathToFileURL } from "node:url";
6	
7	const PREFIX = "@portside/dispatch/";
8	const SRC = join(dirname(fileURLToPath(import.meta.url)), "..", "..", "src");
9	
10	export function resolve(specifier, context, nextResolve) {
11	  if (specifier.startsWith(PREFIX)) {
12	    const file = join(SRC, specifier.slice(PREFIX.length));
13	    if (existsSync(file)) return { url: pathToFileURL(file).href, shortCircuit: true };
14	  }
15	  return nextResolve(specifier, context);
16	}
