#!/usr/bin/env node
// Look up an item in the ops queue:  fetch-ticket <ID> [--json]
import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { inflateSync } from "node:zlib";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const args = process.argv.slice(2);
const ids = args.filter((a) => !a.startsWith("-"));
if (ids.length !== 1) {
  console.error("usage: fetch-ticket <ID> [--json]");
  process.exit(2);
}

function load() {
  const buf = readFileSync(join(root, ".ops/queue.pack"));
  if (buf.subarray(0, 4).toString("latin1") !== "PSQ1") throw new Error("fetch-ticket: unreadable store");
  return JSON.parse(inflateSync(buf.subarray(4)).toString("utf8"));
}

function wrap(text, width = 88) {
  const out = [];
  let line = "";
  for (const word of text.split(/\s+/).filter(Boolean)) {
    if (line && line.length + word.length + 1 > width) {
      out.push(line);
      line = word;
    } else {
      line = line ? `${line} ${word}` : word;
    }
  }
  if (line) out.push(line);
  return out.length ? out : [""];
}

function sortKeys(value) {
  if (Array.isArray(value)) return value.map(sortKeys);
  if (value && typeof value === "object") {
    return Object.fromEntries(Object.keys(value).sort().map((k) => [k, sortKeys(value[k])]));
  }
  return value;
}

const key = ids[0].trim().toUpperCase();
const item = load().find((x) => x.id === key);
if (!item) {
  console.error(`fetch-ticket: no item ${key} in the ops queue`);
  process.exit(1);
}

